<?php

namespace Parle;

use JetBrains\PhpStorm\Immutable;

/**
 * <div id="class.parle-lexer" class="reference"> <h1 class="title">The Parle\Lexer class</h1>  <div class="partintro"><p class="verinfo">(PECL parle &gt;= 0.5.1)</p>  <div class="section" id="parle-lexer.intro">   <h2 class="title">简介</h2>   <p class="para">    Single state lexer class. Lexemes can be defined on the fly. If the particular lexer instance is meant to be used with <span class="classname"><a href="https://php.net/manual/zh/class.parle-parser.php" class="classname">Parle\Parser</a></span>, the token IDs need to be taken from there. Otherwise, arbitrary token IDs can be supplied. This lexer can give a certain performance advantage over <span class="classname"><a href="https://php.net/manual/zh/class.parle-rlexer.php" class="classname">Parle\RLexer</a></span>, if no multiple states are required. Note, that <span class="classname"><a href="https://php.net/manual/zh/class.parle-rparser.php" class="classname">Parle\RParser</a></span> is not compatible with this lexer.   </p>  </div>  <div class="section" id="parle-lexer.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">Parle\Lexer</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.constants.icase"><var class="varname">ICASE</var></a></var><span class="initializer"> = 1</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.constants.dot-not-lf"><var class="varname">DOT_NOT_LF</var></a></var><span class="initializer"> = 2</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.constants.dot-not-cr-lf"><var class="varname">DOT_NOT_CRLF</var></a></var><span class="initializer"> = 4</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.constants.skip-ws"><var class="varname">SKIP_WS</var></a></var><span class="initializer"> = 8</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.constants.match-zero-len"><var class="varname">MATCH_ZERO_LEN</var></a></var><span class="initializer"> = 16</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.props.bol">\$<var class="varname">bol</var></a></var><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.props.flags">\$<var class="varname">flags</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.props.state">\$<var class="varname">state</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.props.marker">\$<var class="varname">marker</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-lexer.php#parle-lexer.props.cursor">\$<var class="varname">cursor</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.advance.php" class="methodname" style="color:#CC7832">advance</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.build.php" class="methodname" style="color:#CC7832">build</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.callout.php" class="methodname" style="color:#CC7832">callout</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.consume.php" class="methodname" style="color:#CC7832">consume</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.dump.php" class="methodname" style="color:#CC7832">dump</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.gettoken.php" class="methodname" style="color:#CC7832">getToken</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.parle-token.php" class="type Parle\Token" style="color:#EAB766">Parle\Token</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.insertmacro.php" class="methodname" style="color:#CC7832">insertMacro</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.push.php" class="methodname" style="color:#CC7832">push</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-lexer.reset.php" class="methodname" style="color:#CC7832">reset</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$pos</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section" id="parle-lexer.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="parle-lexer.constants.icase"><strong><span>{@link Parle\Lexer::ICASE}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-lexer.constants.dot-not-lf"><strong><span>{@link Parle\Lexer::DOT_NOT_LF}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-lexer.constants.dot-not-cr-lf"><strong><span>Parle\Lexer::DOT_NOT_CRLF</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-lexer.constants.skip-ws"><strong><span>{@link Parle\Lexer::SKIP_WS}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-lexer.constants.match-zero-len"><strong><span>{@link Parle\Lexer::MATCH_ZERO_LEN}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div>  <div class="section" id="parle-lexer.props">   <h2 class="title">属性</h2>   <dl>         <dt id="parle-lexer.props.bol"><var class="varname">bol</var></dt>     <dd>      <p class="para">Start of input flag.</p>     </dd>             <dt id="parle-lexer.props.flags"><var class="varname">flags</var></dt>     <dd>      <p class="para">Lexer flags.</p>     </dd>             <dt id="parle-lexer.props.state"><var class="varname">state</var></dt>     <dd>      <p class="para">Current lexer state, readonly.</p>     </dd>             <dt id="parle-lexer.props.marker"><var class="varname">marker</var></dt>     <dd>      <p class="para">Position of the latest token match, readonly.</p>     </dd>             <dt id="parle-lexer.props.cursor"><var class="varname">cursor</var></dt>     <dd>      <p class="para">Current input offset, readonly.</p>     </dd>       </dl>  </div> </div>  <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Parle\Lexer::advance} — Process next lexer rule</li><li>{@link Parle\Lexer::build} — Finalize the lexer rule set</li><li>{@link Parle\Lexer::callout} — Define token callback</li><li>{@link Parle\Lexer::consume} — Pass the data for processing</li><li>{@link Parle\Lexer::dump} — Dump the state machine</li><li>{@link Parle\Lexer::getToken} — Retrieve the current token</li><li>{@link Parle\Lexer::insertMacro} — Insert regex macro</li><li>{@link Parle\Lexer::push} — Add a lexer rule</li><li>{@link Parle\Lexer::reset} — Reset lexer</li></ul></div>
 * 
 * Single state lexer class.
 *
 * Lexemes can be defined on the fly.
 * If the particular lexer instance is meant to be used with Parle\Parser, the token IDs need to be taken from there.
 * Otherwise, arbitrary token IDs can be supplied. This lexer can give a certain performance advantage over Parle\RLexer,
 * if no multiple states are required. Note, that Parle\RParser is not compatible with this lexer.
 *
 * @see Parser
 * @package Parle
 */
class Lexer
{
    /* Constants */
    public const ICASE = 1;
    public const DOT_NOT_LF = 2;
    public const DOT_NOT_CRLF = 4;
    public const SKIP_WS = 8;
    public const MATCH_ZERO_LEN = 16;

    /* Properties */
    /**
     * @var bool Start of input flag.
     */
    public $bol = false;

    /**
     * @var int Lexer flags.
     */
    public $flags = 0;

    /**
     * @var int Current lexer state, readonly.
     */
    #[Immutable]
    public $state = 0;

    /**
     * @var int Position of the latest token match, readonly.
     */
    #[Immutable]
    public $marker = 0;

    /**
     * @var int Current input offset, readonly.
     */
    #[Immutable]
    public $cursor = 0;

    /* Methods */

    /**
 * <div id="parle-lexer.advance" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\Lexer::advance</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\Lexer::advance</span> — <span class="dc-title">Process next lexer rule</span></p> </div> <div class="refsect1 description" id="refsect1-parle-lexer.advance-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\Lexer::advance</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Processes the next rule and prepares the resulting token data.  </p> </div> <div class="refsect1 parameters" id="refsect1-parle-lexer.advance-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-parle-lexer.advance-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Processes the next rule and prepares the resulting token data.
     *
     * @link https://php.net/manual/zh/parle-lexer.advance.php
     * @return void
     */
    public function advance(): void {}

    /**
 * <div id="parle-lexer.build" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\Lexer::build</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\Lexer::build</span> — <span class="dc-title">Finalize the lexer rule set</span></p> </div> <div class="refsect1 description" id="refsect1-parle-lexer.build-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\Lexer::build</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Rules, previously added with <span class="methodname" style="color:#CC7832">{@link Parle\Lexer::push()}</span> are finalized. This method call has to be done after all the necessary rules was pushed. The rule set becomes read only. The lexing can begin.  </p> </div> <div class="refsect1 parameters" id="refsect1-parle-lexer.build-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-parle-lexer.build-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Finalize the lexer rule set
     *
     * Rules, previously added with Parle\Lexer::push() are finalized.
     * This method call has to be done after all the necessary rules was pushed.
     * The rule set becomes read only. The lexing can begin.
     *
     * @see Lexer::push()
     * @link https://php.net/manual/zh/parle-lexer.build.php
     * @return void
     */
    public function build(): void {}

    /**
 * <div id="parle-lexer.callout" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\Lexer::callout</h1>  <p class="verinfo">(PECL parle &gt;= 0.7.2)</p><p class="refpurpose"><span class="refname">Parle\Lexer::callout</span> — <span class="dc-title">Define token callback</span></p> </div> <div class="refsect1 description" id="refsect1-parle-lexer.callout-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\Lexer::callout</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Define a callback to be invoked once lexer encounters a particular token.  </p> </div> <div class="refsect1 parameters" id="refsect1-parle-lexer.callout-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">id</span></dt>    <dd>     <p class="para">      Token id.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>     <p class="para">      Callable to be invoked. The callable doesn't receive any arguments and its return value is ignored.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-parle-lexer.callout-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Define token callback
     *
     * Define a callback to be invoked once lexer encounters a particular token.
     *
     * @link https://php.net/manual/zh/parle-lexer.callout.php
     * @param int $id Token id.
     * @param callable $callback Callable to be invoked. The callable doesn't receive any arguments and its return value is ignored.
     * @return void
     */
    public function callout(int $id, callable $callback): void {}

    /**
 * <div id="parle-lexer.consume" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\Lexer::consume</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\Lexer::consume</span> — <span class="dc-title">Pass the data for processing</span></p> </div> <div class="refsect1 description" id="refsect1-parle-lexer.consume-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\Lexer::consume</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Consume the data for lexing.   </p> </div> <div class="refsect1 parameters" id="refsect1-parle-lexer.consume-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">data</span></dt>    <dd>     <p class="para">      Data to be lexed.           </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-parle-lexer.consume-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Consume the data for lexing.
     *
     * @link https://php.net/manual/zh/parle-lexer.consume.php
     * @param string $data Data to be lexed.
     * @return void
     */
    public function consume(string $data): void {}

    /**
